"""Fresh matched-arm data; confirmation is never generated by prepare()."""
from __future__ import annotations

import sys
from collections import Counter

from common import (ROOT, SOURCE, PROTOCOL, config, IR, load_module, prepare_row,
                    write_rows, write_json, freeze)


def generate_split(split, cfg):
    spec = cfg["splits"][split]
    sys.path.insert(0, str(SOURCE))
    generator = load_module("program002_generator", SOURCE / "actionnet021.py")
    generator.PROTOCOL_ID = PROTOCOL
    generator.BASE.PROTOCOL_ID = PROTOCOL
    renderer = generator.renderer_lineage()
    families = tuple(range(spec["family_start"], spec["family_start"] + spec["families"]))
    records, _, _, _, audit = generator.make_split(
        split, spec["seed"], families,
        tuple(f"program002-{split}-domain-{i}" for i in range(8)), renderer,
    )
    rows = [prepare_row(record) for record in records]
    if len(rows) != spec["records"]:
        raise ValueError("generator count differs from registration")
    if len({row["case_id"] for row in rows}) != len(rows):
        raise ValueError("duplicate generated case ID")
    for row in rows:
        source = row["compiler_input"]
        state = source["program_source"]["initial_state"]
        events = source["program_source"]["submitted_events"]
        result = IR.verify_program(row["completion"], state, events,
                                   source["oracle_state"], source["oracle_certificate"])
        if not result["program_exact"] or not result["accepted_by_verifier"]:
            raise ValueError("oracle failed independent parsing/execution")
        if result["unsafe_authorization"] or result["verified_unsafe_authorization"]:
            raise ValueError("unsafe oracle")
    return rows, audit


def validate_splits(splits):
    for field in ("case_id", "counterfactual_pair_id", "semantic_family"):
        seen = set()
        for rows in splits.values():
            current = {row[field] for row in rows}
            if seen & current:
                raise ValueError(f"split overlap: {field}")
            seen |= current
    for name, rows in splits.items():
        if set(row["compiler_input"]["oracle_certificate"]["decision"] for row in rows) != {
            "ALLOW", "DENY", "ABSTAIN", "CONTESTED", "INVALID"
        }:
            raise ValueError(f"missing decision class: {name}")
        if set(Counter(row["counterfactual_pair_id"] for row in rows).values()) != {2}:
            raise ValueError("incomplete counterfactual pair")


def prepare():
    cfg = config()
    if (ROOT / "prepared/confirmation.jsonl").exists():
        raise ValueError("confirmation already materialized; do not re-prepare")
    splits, audits = {}, {}
    for name in ("train", "development"):
        splits[name], audits[name] = generate_split(name, cfg)
    validate_splits(splits)
    # The new namespace and disjoint family ranges exclude the prior protocol splits.
    for name, rows in splits.items():
        write_rows(ROOT / f"prepared/{name}.jsonl", rows)
    report = {
        "protocol_id": PROTOCOL, "passed": True,
        "counts": {name: len(rows) for name, rows in splits.items()},
        "mechanisms": {name: dict(Counter(r["pair_mechanism"] for r in rows)) for name, rows in splits.items()},
        "generator_audits": audits,
        "oracle_verification_count": sum(map(len, splits.values())),
        "fresh_namespace": PROTOCOL, "families_minimum": 20000,
        "confirmation_materialized": False, "confirmation_reserved": cfg["splits"]["confirmation"],
        "transfer_authorized": False, "binding_authority": False,
    }
    write_json(ROOT / "prepared/qualification.json", report)
    freeze()
    return report


if __name__ == "__main__":
    import json
    print(json.dumps(prepare(), indent=2))